use super::*;
use crate::org::apache::poi::ss::{SpreadsheetVersion::CUR_VERSION,util::CellRangeAddressBase::CellRangeAddressBase};
use serde_json::{Value,json};
use std::panic::{catch_unwind,AssertUnwindSafe};
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");let n=["NullPointerException","IllegalArgumentException","IllegalStateException","RuntimeException","ArrayIndexOutOfBoundsException"].into_iter().find(|n|s.starts_with(n)).unwrap_or(s);json!({"result":n})}}}
fn hex(b:&[u8])->String{b.iter().map(|v|format!("{v:02x}")).collect()}
fn bytes(s:&str)->Vec<u8>{(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()}
fn encoded(ps:&[Ptg])->Value{call(||hex(&serializePtgs(ps)))}
fn token(t:&mut Ptg,p:&Value,sv:SpreadsheetVersion)->Value{let f=CellRangeAddressBase::CellRangeAddressBase(4,9,5,12);let o=CellRangeAddressBase::CellRangeAddressBase(2,9,3,12);let mut out=json!({"sid":t.getSid(),"a1":call(||t.toFormulaString()),"rc":[call(||t.toRCFormulaString(Some(&f),Some(&o),sv,false)),call(||t.toRCFormulaString(Some(&f),Some(&o),sv,true))]});if matches!(t.kind,PtgKind::Add|PtgKind::Subtract|PtgKind::Multiply|PtgKind::Divide|PtgKind::Power|PtgKind::Concat|PtgKind::Equal|PtgKind::LessThan|PtgKind::GreaterThan|PtgKind::LessEqual|PtgKind::GreaterEqual|PtgKind::NotEqual|PtgKind::UnaryMinus|PtgKind::UnaryPlus|PtgKind::Percent|PtgKind::Union|PtgKind::Intersection|PtgKind::Range|PtgKind::Func{..}|PtgKind::FuncVar{..}|PtgKind::FuncVarExt{..}){out["count"]=json!(t.getNumberOfOperands());out["args"]=call(||t.toFormulaString__operands(Some(&[Some("alpha".into()),None,Some("omega".into())]),';','|'));}if matches!(t.kind,PtgKind::Array{..}){out["array"]=call(||t.toArrayFormulaString__separators(',', '|','~'));}if matches!(t.kind,PtgKind::Attr{..}){out["attr"]=json!({"data":t.getAttrData(),"jump":call(||t.getJumpTable()),"offset":call(||t.getChooseFuncOffset()),"text":t.attrToString(),"args":call(||t.toAttrFormulaString__operands(Some(&[None])))});let _=call(||{let mut j=t.getJumpTable();if !j.is_empty(){j[0]=999999;}});out["jumpAfter"]=call(||t.getJumpTable());}if matches!(t.kind,PtgKind::SxName{..}){let mut history=vec![];for a in p["sx"].as_array().unwrap(){t.setFieldName(a["field"].as_str().map(str::to_string));t.setItemName(a["item"].as_str().map(str::to_string));t.setSxIndex(a["index"].as_i64().unwrap()as i32);history.push(json!({"field":t.getFieldName(),"item":t.getItemName(),"index":t.getSxIndex(),"text":t.toSxNameFormulaString()}));}out["sx"]=json!(history);}out}
fn one(p:&Value)->Value{let sv=if p["version"]==97{SpreadsheetVersion::EXCEL97}else{SpreadsheetVersion::EXCEL2007};*CUR_VERSION.lock().unwrap()=sv;let b=bytes(p["bytes"].as_str().unwrap());let mut ps=None;let mut out=json!({"read":call(||{ps=Some(Ptg::readTokens__stream(p["size"].as_i64().unwrap()as i32,&b,p["external"].as_bool().unwrap(),sv));})});if let Some(mut ps)=ps{out["before"]=encoded(&ps);out["tokens"]=json!(ps.iter_mut().map(|t|token(t,p,sv)).collect::<Vec<_>>());out["after"]=encoded(&ps);}out}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}
