fn original_android_scalar_function_array_attr_output(){let p=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m4-edit-save/evidence/ptg-output-r0b56");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let actual=json!({"cases":input["cases"].as_array().unwrap().iter().map(one).collect::<Vec<_>>()});*CUR_VERSION.lock().unwrap()=SpreadsheetVersion::EXCEL2007;std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();compare(&actual,&java,"root");}
